"""HTTP entry point for RiskScope."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .service import Service, ServiceError


def env_address() -> tuple[str, int]:
    raw = os.environ.get("RISKSCOPE_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid RISKSCOPE_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path not in (
            "/market-risk/historical-var",
            "/market-risk/stress-test",
            "/market-risk/var-backtest",
            "/market-risk/var-backtest-validation",
            "/market-risk/covariance-estimate",
            "/market-risk/parametric-var",
            "/market-risk/discounted-cashflow",
            "/credit-risk/counterparty-exposure",
            "/credit-risk/expected-loss-schedule",
            "/liquidity-risk/liquidity-gap",
            "/portfolio-risk/aggregate",
            "/risk-management/limit-check",
        ):
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except (TypeError, ValueError):
            self.send_json(
                400,
                {"error": {"code": "invalid_request", "message": "invalid Content-Length"}},
            )
            return
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            if self.path == "/market-risk/historical-var":
                result = self.service.historical_var(raw)
            elif self.path == "/market-risk/var-backtest":
                result = self.service.var_backtest(raw)
            elif self.path == "/market-risk/var-backtest-validation":
                result = self.service.var_backtest_validation(raw)
            elif self.path == "/market-risk/covariance-estimate":
                result = self.service.covariance_estimate(raw)
            elif self.path == "/market-risk/parametric-var":
                result = self.service.parametric_var(raw)
            elif self.path == "/market-risk/discounted-cashflow":
                result = self.service.discounted_cashflow(raw)
            elif self.path == "/credit-risk/counterparty-exposure":
                result = self.service.counterparty_exposure(raw)
            elif self.path == "/credit-risk/expected-loss-schedule":
                result = self.service.expected_loss_schedule(raw)
            elif self.path == "/liquidity-risk/liquidity-gap":
                result = self.service.liquidity_gap(raw)
            elif self.path == "/portfolio-risk/aggregate":
                result = self.service.portfolio_aggregate(raw)
            elif self.path == "/risk-management/limit-check":
                result = self.service.limit_check(raw)
            else:
                result = self.service.stress_test(raw)
        except ServiceError as exc:
            self.send_json(
                exc.status,
                {"error": {"code": exc.code, "message": exc.message}},
            )
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="riskscope.server", description="市场风险、信用风险与流动性风险管理引擎")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"RiskScope listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

            rate = fx_rates_raw.get(currency, 1.0)
            rate = _strict_float(rate)
            if rate != 1.0:
                raise InvalidInput(
                    message="reporting currency fx rate must be 1"
                )
            used_rates[currency] = 1.0
        else:
            if currency not in fx_rates_raw:
                raise InvalidInput(
                    "missing_fx_rate",
                    f"missing fx rate for currency {currency!r}",
                )
            rate = _strict_float(fx_rates_raw[currency])
            if rate <= 0.0:
                raise InvalidInput()
            used_rates[currency] = rate

    # First-appearance orders: positions drive currencies, books and (with
    # each object's own key order) factors.
    currency_order: list[str] = []
    book_order: list[str] = []
    factor_order: list[str] = []
    seen_currencies: set[str] = set()
    seen_books: set[str] = set()
    seen_factors: set[str] = set()

    converted: list[dict] = []
    for position in positions:
        currency = position["currency"]
        book = position["book"]
        if currency not in seen_currencies:
            seen_currencies.add(currency)
            currency_order.append(currency)
        if book not in seen_books:
            seen_books.add(book)
            book_order.append(book)
        rate = used_rates[currency]
        converted_mv = position["market_value"] * rate
        if not math.isfinite(converted_mv):
            raise InvalidInput(
                message="aggregation produced a non-finite result"
            )
        converted_sensitivities: dict[str, float] = {}
        for factor, value in position["sensitivities"].items():
            if factor not in seen_factors:
                seen_factors.add(factor)
                factor_order.append(factor)
            converted_value = value * rate
            if not math.isfinite(converted_value):
                raise InvalidInput(
                    message="aggregation produced a non-finite result"
                )
            converted_sensitivities[factor] = converted_value
        converted.append(
            {
                "currency": currency,
                "book": book,
                "market_value": converted_mv,
                "sensitivities": converted_sensitivities,
            }
        )

    # Accumulate the portfolio totals as the sequential position sum (input
    # order); the two partitions accumulate the same values grouped by
    # currency and by book.
    currency_acc = {
        currency: {"market_value": 0.0, "sensitivities": {}}
        for currency in currency_order
    }
    book_acc = {
        book: {"market_value": 0.0, "sensitivities": {}} for book in book_order
    }
    total_market_value = 0.0
    total_sensitivities: dict[str, float] = {}
    for entry in converted:
        total_market_value += entry["market_value"]
        for factor, value in entry["sensitivities"].items():
            total_sensitivities[factor] = total_sensitivities.get(factor, 0.0) + value
        for bucket in (
            currency_acc[entry["currency"]],
            book_acc[entry["book"]],
        ):
            bucket["market_value"] += entry["market_value"]
            for factor, value in entry["sensitivities"].items():
                bucket["sensitivities"][factor] = (
                    bucket["sensitivities"].get(factor, 0.0) + value
                )

    for value in [total_market_value, *total_sensitivities.values()]:
        if not math.isfinite(value):
            raise InvalidInput(
                message="aggregation produced a non-finite result"
            )

    def render_details(order: list[str], acc: dict, label: str) -> list[dict]:
        details: list[dict] = []
        market_values: list[float] = []
        for key in order:
            bucket = acc[key]
            if not math.isfinite(bucket["market_value"]) or any(
                not math.isfinite(value)
                for value in bucket["sensitivities"].values()
            ):
                raise InvalidInput(
                    message="aggregation produced a non-finite result"
                )
            sensitivities = {
                factor: bucket["sensitivities"].get(factor, 0.0)
                for factor in factor_order
            }
            detail = {
                label: key,
                "position_count": 0,
                "converted_market_value": bucket["market_value"],
                "converted_sensitivities": sensitivities,
            }
            details.append(detail)
            market_values.append(bucket["market_value"])
        # Fold the grouped sums onto the sequential portfolio total so
        # each layer's totals equal the sum of its details exactly.
        _reconcile_totals(market_values, total_market_value)
        for index, key in enumerate(order):
            details[index]["converted_market_value"] = market_values[index]
        for factor in factor_order:
            factor_values = [
                detail["converted_sensitivities"][factor] for detail in details
            ]
            _reconcile_totals(
                factor_values, total_sensitivities.get(factor, 0.0)
            )
            for index in range(len(details)):
                details[index]["converted_sensitivities"][factor] = (
                    factor_values[index]
                )
        return details

    position_counts: dict[str, int] = {key: 0 for key in currency_order}
    book_counts: dict[str, int] = {key: 0 for key in book_order}
    for entry in converted:
        position_counts[entry["currency"]] += 1
        book_counts[entry["book"]] += 1

    currency_details = render_details(currency_order, currency_acc, "currency")
    book_details = render_details(book_order, book_acc, "book")
    for detail, key in zip(currency_details, currency_order):
        detail["position_count"] = position_counts[key]
        detail["fx_rate"] = used_rates[key]
    for detail, key in zip(book_details, book_order):
        detail["position_count"] = book_counts[key]

    return {
        "reporting_currency": reporting_currency,
        "position_count": len(positions),
        "currencies": currency_details,
        "books": book_details,
        "portfolio_totals": {
            "converted_market_value": total_market_value,
            "converted_sensitivities": {
                factor: total_sensitivities.get(factor, 0.0)
                for factor in factor_order
            },
        },
    }

def _limit_check(self, payload: dict) -> dict:
    as_of = payload.get("as_of")
    if not _is_nonempty_str(as_of):
        raise InvalidInput()

    limits_raw = payload.get("limits")
    if not isinstance(limits_raw, list) or len(limits_raw) == 0:
        raise InvalidInput()
    if len(limits_raw) > MAX_LIMITS:
        raise RequestTooLarge(f"at most {MAX_LIMITS} limits are allowed")
    limits: list[dict] = []
    for item in limits_raw:
        if not isinstance(item, dict):
            raise InvalidInput()
        limit_id = item.get("id")
        if not _is_nonempty_str(limit_id):
            raise InvalidInput()
        scope = item.get("scope")
        if not isinstance(scope, dict):
            raise InvalidInput()
        scope_type = scope.get("type")
        scope_id = scope.get("id")
        if not _is_nonempty_str(scope_type) or not _is_nonempty_str(scope_id):
            raise InvalidInput()
        metric = item.get("metric")
        if not _is_nonempty_str(metric):
            raise InvalidInput()
        unit = item.get("unit")
        if not _is_nonempty_str(unit):
            raise InvalidInput()
        limit_value = _strict_float(item.get("limit"))
        if limit_value <= 0.0:
            raise InvalidInput()
        warning_ratio = _strict_float(item.get("warning_ratio", 0.8))
        if not 0.0 < warning_ratio < 1.0:
            raise InvalidInput()
        limits.append(
            {
                "id": limit_id,
                "scope": {"type": scope_type, "id": scope_id},
                "metric": metric,
                "unit": unit,
                "limit": limit_value,
                "warning_ratio": warning_ratio,
            }
        )

    seen_limit_ids: set[str] = set()
    for limit in limits:
        if limit["id"] in seen_limit_ids:
            raise InvalidInput("duplicate_limit", "limit ids must be unique")
        seen_limit_ids.add(limit["id"])

    measurements_raw = payload.get("measurements", [])
    if not isinstance(measurements_raw, list):
        raise InvalidInput()
    if len(measurements_raw) > MAX_MEASUREMENTS:
        raise RequestTooLarge(
            f"at most {MAX_MEASUREMENTS} measurements are allowed"
        )
    measurements: list[dict] = []
    for item in measurements_raw:
        if not isinstance(item, dict):
            raise InvalidInput()
        limit_id = item.get("limit_id")
        if not _is_nonempty_str(limit_id):
            raise InvalidInput()
        value = _strict_float(item.get("value"))
        if value < 0.0:
            raise InvalidInput()
        measurements.append({"limit_id": limit_id, "value": value})

    values_by_limit: dict[str, float] = {}
    for measurement in measurements:
        limit_id = measurement["limit_id"]
        if limit_id not in seen_limit_ids:
            raise InvalidInput(
                "unknown_limit",
                f"measurement references undeclared limit {limit_id!r}",
            )
        if limit_id in values_by_limit:
            raise InvalidInput(
                "duplicate_measurement",
                "at most one measurement per limit is allowed",
            )
        values_by_limit[limit_id] = measurement["value"]

    results: list[dict] = []
    alerts: list[dict] = []
    summary = {"ok": 0, "warning": 0, "breach": 0, "no_data": 0}
    for limit in limits:
        entry = dict(limit)
        if limit["id"] in values_by_limit:
            value = values_by_limit[limit["id"]]
            limit_value = limit["limit"]
            utilization = value / limit_value
            headroom = limit_value - value
            if not math.isfinite(utilization) or not math.isfinite(headroom):
                raise InvalidInput(
                    message="limit check produced a non-finite result"
                )
            if value >= limit_value:
                status = "breach"
            elif value >= limit_value * limit["warning_ratio"]:
                status = "warning"
            else:
                status = "ok"
            entry.update(
                {
                    "value": value,
                    "utilization": utilization,
                    "headroom": headroom,
                    "status": status,
                }
            )
        else:
            status = "no_data"
            entry.update(
                {
                    "value": None,
                    "utilization": None,
                    "headroom": None,
                    "status": status,
                }
            )
        summary[status] += 1
        results.append(entry)
        if status in ("warning", "breach"):
            alerts.append(entry)

    if summary["breach"] > 0:
        overall_status = "breach"
    elif summary["warning"] > 0:
        overall_status = "warning"
    elif summary["no_data"] > 0:
        overall_status = "incomplete"
    else:
        overall_status = "ok"

    return {
        "as_of": as_of,
        "limits": results,
        "alerts": alerts,
        "summary": summary,
        "overall_status": overall_status,
    }

def _expected_loss_schedule(self, payload: dict) -> dict:
    currency = payload.get("currency", "USD")
    if not _is_nonempty_str(currency):
        raise InvalidInput()

    periods_raw = payload.get("periods")
    if not isinstance(periods_raw, list) or len(periods_raw) == 0:
        raise InvalidInput()
    periods: list[int] = []
    for period in periods_raw:
        value = _strict_int(period)
        if value <= 0:
            raise InvalidInput()
        periods.append(value)
    # Strictly increasing terms; duplicates cannot satisfy that.
    for earlier, later in zip(periods, periods[1:]):
        if later <= earlier:
            raise InvalidInput(message="periods must be strictly increasing")
    period_count = len(periods)

    discount_factors_raw = payload.get("discount_factors")
    if not isinstance(discount_factors_raw, list) or len(discount_factors_raw) != period_count:
        raise InvalidInput()
    discount_factors: list[float] = []
    for value in discount_factors_raw:
        factor = _strict_float(value)
        if not 0.0 < factor <= 1.0:
            raise InvalidInput()
        discount_factors.append(factor)

    counterparties_raw = payload.get("counterparties")
    if not isinstance(counterparties_raw, list) or len(counterparties_raw) == 0:
        raise InvalidInput()
    if len(counterparties_raw) > MAX_SCHEDULE_COUNTERPARTIES:
        raise RequestTooLarge(
            f"at most {MAX_SCHEDULE_COUNTERPARTIES} counterparties are allowed"
        )
    counterparties: list[dict] = []
    for counterparty in counterparties_raw:
        if not isinstance(counterparty, dict):
            raise InvalidInput()
        counterparty_id = counterparty.get("id")
        if not _is_nonempty_str(counterparty_id):
            raise InvalidInput()
        cumulative_raw = counterparty.get("cumulative_pd")
        if not isinstance(cumulative_raw, list) or len(cumulative_raw) != period_count:
            raise InvalidInput()
        cumulative_pd: list[float] = []
        for value in cumulative_raw:
            pd = _strict_float(value)
            if not 0.0 <= pd <= 1.0:
                raise InvalidInput()
            cumulative_pd.append(pd)
        # A cumulative default probability never falls with the term.
        for earlier, later in zip(cumulative_pd, cumulative_pd[1:]):
            if later < earlier:
                raise InvalidInput(
                    message="cumulative_pd must not decrease across periods"
                )
        counterparties.append({"id": counterparty_id, "cumulative_pd": cumulative_pd})

    facilities_raw = payload.get("facilities")
    if not isinstance(facilities_raw, list) or len(facilities_raw) == 0:
        raise InvalidInput()
    if len(facilities_raw) > MAX_SCHEDULE_FACILITIES:
        raise RequestTooLarge(
            f"at most {MAX_SCHEDULE_FACILITIES} facilities are allowed"
        )
    if period_count * len(facilities_raw) > MAX_SCHEDULE_PERIOD_FACILITY_PAIRS:
        raise RequestTooLarge(
            "periods times facilities must not exceed "
            f"{MAX_SCHEDULE_PERIOD_FACILITY_PAIRS}"
        )
    facilities: list[dict] = []
    for facility in facilities_raw:
        if not isinstance(facility, dict):
            raise InvalidInput()
        facility_id = facility.get("id")
        if not _is_nonempty_str(facility_id):
            raise InvalidInput()
        counterparty_id = facility.get("counterparty_id")
        if not _is_nonempty_str(counterparty_id):
            raise InvalidInput()
        lgd = _strict_float(facility.get("lgd"))
        if not 0.0 <= lgd <= 1.0:
            raise InvalidInput()
        ead_raw = facility.get("ead")
        if not isinstance(ead_raw, list) or len(ead_raw) != period_count:
            raise InvalidInput()
        ead: list[float] = []
        for value in ead_raw:
            amount = _strict_float(value)
            if amount < 0.0:
                raise InvalidInput()
            ead.append(amount)
        facilities.append(
            {
                "id": facility_id,
                "counterparty_id": counterparty_id,
                "lgd": lgd,
                "ead": ead,
            }
        )

    seen_counterparty_ids: set[str] = set()
    for counterparty in counterparties:
        if counterparty["id"] in seen_counterparty_ids:
            raise InvalidInput(
                "duplicate_counterparty", "counterparty ids must be unique"
            )
        seen_counterparty_ids.add(counterparty["id"])

    seen_facility_ids: set[str] = set()
    for facility in facilities:
        if facility["id"] in seen_facility_ids:
            raise InvalidInput("duplicate_facility", "facility ids must be unique")
        seen_facility_ids.add(facility["id"])

    counterparty_by_id = {cp["id"]: cp for cp in counterparties}
    for facility in facilities:
        if facility["counterparty_id"] not in counterparty_by_id:
            raise InvalidInput(
                "unknown_counterparty",
                "facility references an unknown counterparty "
                f"{facility['counterparty_id']!r}",
            )

    def non_finite() -> InvalidInput:
        return InvalidInput(
            message="schedule computation produced a non-finite result"
        )

    # Marginal default probability per counterparty: the first period
    # takes the first cumulative value, later periods the difference
    # of adjacent cumulative values.
    marginal_pd: dict[str, list[float]] = {}
    for counterparty in counterparties:
        cumulative_pd = counterparty["cumulative_pd"]
        marginal = [cumulative_pd[0]]
        for index in range(1, period_count):
            marginal.append(cumulative_pd[index] - cumulative_pd[index - 1])
        marginal_pd[counterparty["id"]] = marginal

    facility_values: list[list[float]] = []
    facility_totals: list[float] = []
    facility_results: list[dict] = []
    for facility in facilities:
        marginal = marginal_pd[facility["counterparty_id"]]
        lgd = facility["lgd"]
        values: list[float] = []
        for index in range(period_count):
            value = (
                facility["ead"][index]
                * lgd
                * marginal[index]
                * discount_factors[index]
            )
            if not math.isfinite(value):
                raise non_finite()
            values.append(value)
        total = 0.0
        for value in values:
            total += value
            if not math.isfinite(total):
                raise non_finite()
        facility_values.append(values)
        facility_totals.append(total)
        facility_results.append(
            {
                "id": facility["id"],
                "counterparty_id": facility["counterparty_id"],
                "contributions": [
                    {
                        "period": periods[index],
                        "discounted_expected_loss": values[index],
                    }
                    for index in range(period_count)
                ],
                "total_discounted_expected_loss": total,
            }
        )

    # Aggregate in input order at both levels so each layer's totals
    # are exactly the sequential sum of the layer below. The per-period
    # lists are folded onto those totals so each layer's total also
    # equals the sum of its own per-period contributions exactly.
    counterparty_results: list[dict] = []
    counterparty_period_values: list[list[float]] = []
    counterparty_totals: list[float] = []
    for counterparty in counterparties:
        owned = [
            index
            for index, facility in enumerate(facilities)
            if facility["counterparty_id"] == counterparty["id"]
        ]
        per_period = [0.0] * period_count
        for index in owned:
            for period_index in range(period_count):
                per_period[period_index] += facility_values[index][period_index]
                if not math.isfinite(per_period[period_index]):
                    raise non_finite()
        total = 0.0
        for index in owned:
            total += facility_totals[index]
            if not math.isfinite(total):
                raise non_finite()
        _reconcile_totals(per_period, total)
        counterparty_period_values.append(per_period)
        counterparty_totals.append(total)
        counterparty_results.append(
            {
                "id": counterparty["id"],
                "contributions": [
                    {
                        "period": periods[index],
                        "discounted_expected_loss": per_period[index],
                    }
                    for index in range(period_count)
                ],
                "total_discounted_expected_loss": total,
            }
        )

    portfolio_per_period = [0.0] * period_count
    for per_period in counterparty_period_values:
        for period_index in range(period_count):
            portfolio_per_period[period_index] += per_period[period_index]
            if not math.isfinite(portfolio_per_period[period_index]):
                raise non_finite()
    portfolio_total = 0.0
    for total in counterparty_totals:
        portfolio_total += total
        if not math.isfinite(portfolio_total):
            raise non_finite()
    _reconcile_totals(portfolio_per_period, portfolio_total)

    return {
        "currency": currency,
        "periods": periods,
        "facilities": facility_results,
        "counterparties": counterparty_results,
        "portfolio_total": {
            "contributions": [
                {
                    "period": periods[index],
                    "discounted_expected_loss": portfolio_per_period[index],
                }
                for index in range(period_count)
            ],
            "total_discounted_expected_loss": portfolio_total,
        },
    }

def _discounted_cashflow(self, payload: dict) -> dict:
    currency = payload.get("currency", "USD")
    if not _is_nonempty_str(currency):
        raise InvalidInput()

    curve_raw = payload.get("curve_points")
    if not isinstance(curve_raw, list):
        raise InvalidInput()
    if len(curve_raw) > MAX_CURVE_POINTS:
        raise RequestTooLarge(
            f"at most {MAX_CURVE_POINTS} curve points are allowed"
        )
    if len(curve_raw) < 2:
        raise InvalidInput()
    curve_points: list[dict] = []
    for point in curve_raw:
        if not isinstance(point, dict):
            raise InvalidInput()
        day = _strict_day(point.get("day"))
        zero_rate = _strict_float(point.get("zero_rate"))
        curve_points.append({"day": day, "zero_rate": zero_rate})

    positions_raw = payload.get("positions")
    if not isinstance(positions_raw, list) or len(positions_raw) == 0:
        raise InvalidInput()
    if len(positions_raw) > MAX_POSITIONS:
        raise RequestTooLarge(f"at most {MAX_POSITIONS} positions are allowed")
    positions: list[dict] = []
    cashflow_count = 0
    for position in positions_raw:
        if not isinstance(position, dict):
            raise InvalidInput()
        position_id = position.get("id")
        if not _is_nonempty_str(position_id):
            raise InvalidInput()
        cashflows_raw = position.get("cashflows")
        if not isinstance(cashflows_raw, list) or len(cashflows_raw) == 0:
            raise InvalidInput()
        cashflows: list[dict] = []
        for cashflow in cashflows_raw:
            if not isinstance(cashflow, dict):
                raise InvalidInput()
            day = _strict_day(cashflow.get("day"))
            amount = _strict_float(cashflow.get("amount"))
            cashflows.append({"day": day, "amount": amount})
        cashflow_count += len(cashflows)
        positions.append({"id": position_id, "cashflows": cashflows})
    if cashflow_count > MAX_CASHFLOWS:
        raise RequestTooLarge(
            f"at most {MAX_CASHFLOWS} cashflows are allowed"
        )

    seen_days: set[int] = set()
    for point in curve_points:
        if point["day"] in seen_days:
            raise InvalidInput(
                "duplicate_curve_point", "curve point days must be unique"
            )
        seen_days.add(point["day"])

    seen_position_ids: set[str] = set()
    for position in positions:
        if position["id"] in seen_position_ids:
            raise InvalidInput("duplicate_position", "position ids must be unique")
        seen_position_ids.add(position["id"])

    # The curve may arrive unordered; valuation and the echoed curve
    # both use ascending day order.
    curve_points.sort(key=lambda point: point["day"])
    node_days = [point["day"] for point in curve_points]
    node_rates = [point["zero_rate"] for point in curve_points]
    node_count = len(node_days)

    def non_finite() -> InvalidInput:
        return InvalidInput(
            message="discount computation produced a non-finite result"
        )

    def locate(day: int) -> tuple[float, list[tuple[int, float]]]:
        """Zero rate and per-node interpolation weights for ``day``."""
        if day < node_days[0] or day > node_days[-1]:
            raise InvalidInput(
                "curve_out_of_range",
                "cashflow day lies outside the curve",
            )
        index = bisect.bisect_left(node_days, day)
        if node_days[index] == day:
            return node_rates[index], [(index, 1.0)]
        left, right = index - 1, index
        span = node_days[right] - node_days[left]
        weight_left = (node_days[right] - day) / span
        weight_right = (day - node_days[left]) / span
        rate = (
            node_rates[left] * weight_left + node_rates[right] * weight_right
        )
        return rate, [(left, weight_left), (right, weight_right)]

    position_results: list[dict] = []
    position_node_sensitivities: list[list[float]] = []
    for position in positions:
        present_value = 0.0
        node_sensitivities = [0.0] * node_count
        for cashflow in position["cashflows"]:
            rate, weights = locate(cashflow["day"])
            t = cashflow["day"] / 365.0
            exponent = -rate * t
            if not math.isfinite(exponent):
                raise non_finite()
            try:
                discount = math.exp(exponent)
            except OverflowError:
                raise non_finite()
            pv = cashflow["amount"] * discount
            if not math.isfinite(pv):
                raise non_finite()
            base = pv * t * 0.0001
            if not math.isfinite(base):
                raise non_finite()
            present_value += pv
            if not math.isfinite(present_value):
                raise non_finite()
            for node_index, weight in weights:
                contribution = base * weight
                if not math.isfinite(contribution):
                    raise non_finite()
                node_sensitivities[node_index] += contribution
                if not math.isfinite(node_sensitivities[node_index]):
                    raise non_finite()
        # dv01 is the sum of this level's node sensitivities, folded
        # in ascending node order; zero entries stay visible.
        dv01 = 0.0
        for value in node_sensitivities:
            dv01 += value
            if not math.isfinite(dv01):
                raise non_finite()
        position_node_sensitivities.append(node_sensitivities)
        position_results.append(
            {
                "id": position["id"],
                "present_value": present_value,
                "dv01": dv01,
                "key_rate_dv01": [
                    {"day": node_days[i], "key_rate_dv01": node_sensitivities[i]}
                    for i in range(node_count)
                ],
            }
        )

    # Portfolio totals accumulate the position layer in input order.
    portfolio_present_value = 0.0
    portfolio_node_sensitivities = [0.0] * node_count
    for result, node_sensitivities in zip(
        position_results, position_node_sensitivities
    ):
        portfolio_present_value += result["present_value"]
        if not math.isfinite(portfolio_present_value):
            raise non_finite()
        for i in range(node_count):
            portfolio_node_sensitivities[i] += node_sensitivities[i]
            if not math.isfinite(portfolio_node_sensitivities[i]):
                raise non_finite()
    portfolio_dv01 = 0.0
    for value in portfolio_node_sensitivities:
        portfolio_dv01 += value
        if not math.isfinite(portfolio_dv01):
            raise non_finite()

    return {
        "currency": currency,
        "curve_points": [
            {"day": node_days[i], "zero_rate": node_rates[i]}
            for i in range(node_count)
        ],
        "positions": position_results,
        "portfolio_totals": {
            "present_value": portfolio_present_value,
            "dv01": portfolio_dv01,
            "key_rate_dv01": [
                {
                    "day": node_days[i],
                    "key_rate_dv01": portfolio_node_sensitivities[i],
                }
                for i in range(node_count)
            ],
        },
    }

import json
import unittest

from riskscope.service import (
    InvalidInput,
    InvalidRequest,
    RequestTooLarge,
    Service,
)


def request_body(**overrides):
    body = {
        "periods": [1, 2, 3],
        "discount_factors": [1.0, 0.5, 0.25],
        "counterparties": [
            {"id": "cp-a", "cumulative_pd": [0.125, 0.25, 0.5]},
            {"id": "cp-b", "cumulative_pd": [0.0, 0.0, 0.5]},
        ],
        "facilities": [
            {"id": "f-1", "counterparty_id": "cp-a", "lgd": 0.5,
             "ead": [100.0, 200.0, 400.0]},
            {"id": "f-2", "counterparty_id": "cp-a", "lgd": 1.0,
             "ead": [8.0, 16.0, 32.0]},
        ],
    }
    body.update(overrides)
    return json.dumps(body).encode("utf-8")


class ExpectedLossScheduleTest(unittest.TestCase):
    def setUp(self):
        self.service = Service()

    def call(self, **overrides):
        return self.service.expected_loss_schedule(request_body(**overrides))

    # ---- success shapes and values ----

    def test_basic_shapes_and_values(self):
        result = self.call()
        self.assertEqual(result["currency"], "USD")
        self.assertEqual(result["periods"], [1, 2, 3])

        facilities = result["facilities"]
        self.assertEqual([f["id"] for f in facilities], ["f-1", "f-2"])

        # Marginal pd of cp-a: [0.125, 0.125, 0.25].
        f1 = facilities[0]
        self.assertEqual(f1["counterparty_id"], "cp-a")
        self.assertEqual(
            [c["period"] for c in f1["contributions"]], [1, 2, 3]
        )
        self.assertEqual(
            [c["discounted_expected_loss"] for c in f1["contributions"]],
            [6.25, 6.25, 12.5],
        )
        self.assertEqual(f1["total_discounted_expected_loss"], 25.0)

        f2 = facilities[1]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in f2["contributions"]],
            [1.0, 1.0, 2.0],
        )
        self.assertEqual(f2["total_discounted_expected_loss"], 4.0)

    def test_counterparty_and_portfolio_aggregation(self):
        result = self.call()
        counterparties = result["counterparties"]
        self.assertEqual([cp["id"] for cp in counterparties], ["cp-a", "cp-b"])

        cp_a = counterparties[0]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in cp_a["contributions"]],
            [7.25, 7.25, 14.5],
        )
        self.assertEqual(cp_a["total_discounted_expected_loss"], 29.0)

        # cp-b has no facilities: all-zero results are kept, not omitted.
        cp_b = counterparties[1]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in cp_b["contributions"]],
            [0.0, 0.0, 0.0],
        )
        self.assertEqual(cp_b["total_discounted_expected_loss"], 0.0)

        portfolio = result["portfolio_total"]
        self.assertEqual(
            [c["period"] for c in portfolio["contributions"]], [1, 2, 3]
        )
        self.assertEqual(
            [c["discounted_expected_loss"] for c in portfolio["contributions"]],
            [7.25, 7.25, 14.5],
        )
        self.assertEqual(portfolio["total_discounted_expected_loss"], 29.0)

    def test_layer_totals_match_details(self):
        result = self.call()
        facilities = result["facilities"]
        counterparties = result["counterparties"]
        portfolio = result["portfolio_total"]

        for facility in facilities:
            self.assertEqual(
                facility["total_discounted_expected_loss"],
                sum(c["discounted_expected_loss"] for c in facility["contributions"]),
            )
        for cp_row, cp_id in zip(counterparties, ["cp-a", "cp-b"]):
            owned = [f for f in facilities if f["counterparty_id"] == cp_id]
            for index in range(3):
                self.assertEqual(
                    cp_row["contributions"][index]["discounted_expected_loss"],
                    sum(
                        f["contributions"][index]["discounted_expected_loss"]
                        for f in owned
                    ),
                )
            self.assertEqual(
                cp_row["total_discounted_expected_loss"],
                sum(f["total_discounted_expected_loss"] for f in owned),
            )
            self.assertEqual(
                cp_row["total_discounted_expected_loss"],
                sum(c["discounted_expected_loss"] for c in cp_row["contributions"]),
            )
        for index in range(3):
            self.assertEqual(
                portfolio["contributions"][index]["discounted_expected_loss"],
                sum(
                    cp["contributions"][index]["discounted_expected_loss"]
                    for cp in counterparties
                ),
            )
        self.assertEqual(
            portfolio["total_discounted_expected_loss"],
            sum(cp["total_discounted_expected_loss"] for cp in counterparties),
        )
        self.assertEqual(
            portfolio["total_discounted_expected_loss"],
            sum(c["discounted_expected_loss"] for c in portfolio["contributions"]),
        )

    def test_first_period_marginal_pd_is_the_cumulative_value(self):
        result = self.call(
            periods=[5],
            discount_factors=[1.0],
            counterparties=[{"id": "c", "cumulative_pd": [0.25]}],
            facilities=[
                {"id": "f", "counterparty_id": "c", "lgd": 0.5, "ead": [40.0]}
            ],
        )
        facility = result["facilities"][0]
        # 40.0 * 0.5 * 0.25 * 1.0
        self.assertEqual(
            facility["contributions"][0]["discounted_expected_loss"], 5.0
        )
        self.assertEqual(facility["total_discounted_expected_loss"], 5.0)

    def test_zero_marginal_pd_periods_keep_zero_contributions(self):
        result = self.call(
            periods=[1, 2],
            discount_factors=[1.0, 1.0],
            counterparties=[{"id": "c", "cumulative_pd": [0.5, 0.5]}],
            facilities=[
                {"id": "f", "counterparty_id": "c", "lgd": 1.0, "ead": [10.0, 10.0]}
            ],
        )
        facility = result["facilities"][0]
        # Marginal pd is [0.5, 0.0]: the flat cumulative curve defaults
        # only in the first period.
        self.assertEqual(
            [c["discounted_expected_loss"] for c in facility["contributions"]],
            [5.0, 0.0],
        )

    def test_currency_echo_and_default(self):
        self.assertEqual(self.call()["currency"], "USD")
        self.assertEqual(self.call(currency="EUR")["currency"], "EUR")

    def test_extra_fields_are_ignored(self):
        result = self.call(
            unexpected="top-level",
            counterparties=[
                {"id": "c", "cumulative_pd": [0.5, 0.5, 0.5], "rating": "AAA"}
            ],
            facilities=[
                {"id": "f", "counterparty_id": "c", "lgd": 1.0,
                 "ead": [2.0, 2.0, 2.0], "note": 1}
            ],
        )
        facility = result["facilities"][0]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in facility["contributions"]],
            [1.0, 0.0, 0.0],
        )

    def test_integer_numbers_are_accepted(self):
        result = self.call(
            periods=[1, 2],
            discount_factors=[1, 1],
            counterparties=[{"id": "c", "cumulative_pd": [1, 1]}],
            facilities=[
                {"id": "f", "counterparty_id": "c", "lgd": 1, "ead": [10, 20]}
            ],
        )
        facility = result["facilities"][0]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in facility["contributions"]],
            [10.0, 0.0],
        )
        self.assertEqual(facility["total_discounted_expected_loss"], 10.0)

    # ---- 400 invalid_request ----

    def test_unparseable_json_is_invalid_request(self):
        with self.assertRaises(InvalidRequest) as ctx:
            self.service.expected_loss_schedule(b"{not json")
        self.assertEqual(ctx.exception.status, 400)
        self.assertEqual(ctx.exception.code, "invalid_request")

    def test_non_object_payload_is_invalid_request(self):
        for raw in (b"[1, 2]", b"42", b'"text"', b"null"):
            with self.assertRaises(InvalidRequest):
                self.service.expected_loss_schedule(raw)

    # ---- 422 invalid_input: structure, types, ranges ----

    def test_missing_and_empty_arrays(self):
        for key in ("periods", "discount_factors", "counterparties", "facilities"):
            with self.assertRaises(InvalidInput):
                self.call(**{key: None})
            with self.assertRaises(InvalidInput):
                self.call(**{key: []})
            with self.assertRaises(InvalidInput):
                self.call(**{key: "not-a-list"})

    def test_currency_must_be_nonempty_string(self):
        for bad in ("", 3, None, True):
            with self.assertRaises(InvalidInput):
                self.call(currency=bad)

    def test_periods_validation(self):
        bad_periods = [
            [0],            # not positive
            [-1],           # negative
            [1.5],          # not an integer
            [True],         # bool is not an integer term
            ["1"],          # string
            [2, 1],         # not increasing
            [1, 1],         # duplicate
            [1, 3, 2],      # not increasing
            [None],         # missing value
        ]
        for periods in bad_periods:
            with self.assertRaises(InvalidInput, msg=repr(periods)):
                self.call(periods=periods)

    def test_discount_factors_validation(self):
        bad_factors = [
            [1.0, 0.5],             # length mismatch
            [1.0, 0.5, 0.25, 0.1],  # length mismatch
            [1.0, 0.0, 0.25],       # zero not allowed
            [1.0, -0.5, 0.25],      # negative
            [1.0, 1.5, 0.25],       # above 1
            [1.0, True, 0.25],      # bool
            [1.0, "0.5", 0.25],     # string
            [1.0, 10**400, 0.25],   # oversized integer
            [1.0, None, 0.25],      # missing value
        ]
        for factors in bad_factors:
            with self.assertRaises(InvalidInput, msg=repr(factors)):
                self.call(discount_factors=factors)

    def test_discount_factor_boundaries_are_allowed(self):
        result = self.call(discount_factors=[1.0, 1.0, 1.0])
        # f-1: [6.25, 12.5, 50.0]; f-2: [1.0, 2.0, 8.0].
        self.assertEqual(
            result["portfolio_total"]["total_discounted_expected_loss"], 79.75
        )

    def test_counterparty_field_validation(self):
        bad_counterparties = [
            [{"cumulative_pd": [0.1, 0.2, 0.3]}],  # missing id
            [{"id": "", "cumulative_pd": [0.1, 0.2, 0.3]}],
            [{"id": "c"}],  # missing cumulative_pd
            [{"id": "c", "cumulative_pd": "not-a-list"}],
            [{"id": "c", "cumulative_pd": [0.1, 0.2]}],        # length mismatch
            [{"id": "c", "cumulative_pd": [0.1, 0.2, 0.3, 0.4]}],
            [{"id": "c", "cumulative_pd": [-0.1, 0.2, 0.3]}],  # below 0
            [{"id": "c", "cumulative_pd": [0.1, 0.2, 1.1]}],   # above 1
            [{"id": "c", "cumulative_pd": [0.3, 0.2, 0.3]}],   # decreasing
            [{"id": "c", "cumulative_pd": [True, 0.2, 0.3]}],  # bool
            [{"id": "c", "cumulative_pd": ["0.1", 0.2, 0.3]}],  # string
            [{"id": "c", "cumulative_pd": [10**400, 1.0, 1.0]}],  # oversized
            ["not-an-object"],
        ]
        for counterparties in bad_counterparties:
            with self.assertRaises(InvalidInput, msg=repr(counterparties)):
                self.call(counterparties=counterparties)

    def test_cumulative_pd_boundaries_are_allowed(self):
        result = self.call(
            counterparties=[{"id": "c", "cumulative_pd": [0.0, 1.0, 1.0]}],
            facilities=[
                {"id": "f", "counterparty_id": "c", "lgd": 1.0,
                 "ead": [10.0, 10.0, 10.0]}
            ],
        )
        facility = result["facilities"][0]
        self.assertEqual(
            [c["discounted_expected_loss"] for c in facility["contributions"]],
            [0.0, 5.0, 0.0],
        )

    def test_facility_field_validation(self):
        bad_facilities = [
            [{"counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "lgd": 0.5, "ead": [1.0, 1.0, 1.0]}],  # missing cp id
            [{"id": "f", "counterparty_id": "", "lgd": 0.5, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": -0.1, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 1.1, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": True, "ead": [1.0, 1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5}],  # missing ead
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": "x"}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, -1.0, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, False, 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, "1", 1.0]}],
            [{"id": "f", "counterparty_id": "cp-a", "lgd": 0.5, "ead": [1.0, 10**400, 1.0]}],
            ["not-an-object"],
        ]
        for facilities in bad_facilities:
            with self.assertRaises(InvalidInput, msg=repr(facilities)):
                self.call(facilities=facilities)

    def test_nan_and_infinity_tokens_are_invalid_input(self):
        for token in ("NaN", "Infinity", "-Infinity"):
            raw = request_body().replace(b"100.0", token.encode())
            with self.assertRaises(InvalidInput):
                self.service.expected_loss_schedule(raw)

    def test_non_finite_computation_is_invalid_input(self):
        with self.assertRaises(InvalidInput):
            self.call(
                periods=[1],
                discount_factors=[1.0],
                counterparties=[{"id": "c", "cumulative_pd": [1.0]}],
                facilities=[
                    {"id": "f-1", "counterparty_id": "c", "lgd": 1.0, "ead": [1e308]},
                    {"id": "f-2", "counterparty_id": "c", "lgd": 1.0, "ead": [1e308]},
                ],
            )

    # ---- 422 duplicate_* / unknown_counterparty ----

    def assert_code(self, code, **overrides):
        with self.assertRaises(InvalidInput) as ctx:
            self.call(**overrides)
        self.assertEqual(ctx.exception.code, code)
        self.assertEqual(ctx.exception.status, 422)

    def test_duplicate_ids(self):
        self.assert_code(
            "duplicate_counterparty",
            counterparties=[
                {"id": "c", "cumulative_pd": [0.1, 0.2, 0.3]},
                {"id": "c", "cumulative_pd": [0.1, 0.2, 0.3]},
            ],
        )
        self.assert_code(
            "duplicate_facility",
            facilities=[
                {"id": "f", "counterparty_id": "cp-a", "lgd": 0.5,
                 "ead": [1.0, 1.0, 1.0]},
                {"id": "f", "counterparty_id": "cp-b", "lgd": 0.5,
                 "ead": [1.0, 1.0, 1.0]},
            ],
        )

    def test_unknown_counterparty(self):
        self.assert_code(
            "unknown_counterparty",
            facilities=[
                {"id": "f", "counterparty_id": "ghost", "lgd": 0.5,
                 "ead": [1.0, 1.0, 1.0]}
            ],
        )

    # ---- 413 request_too_large ----

    def test_size_limits(self):
        counterparties = [
            {"id": f"cp-{i}", "cumulative_pd": [0.1, 0.2, 0.3]}
            for i in range(1001)
        ]
        with self.assertRaises(RequestTooLarge) as ctx:
            self.call(counterparties=counterparties)
        self.assertEqual(ctx.exception.status, 413)
        self.assertEqual(ctx.exception.code, "request_too_large")

        facilities = [
            {"id": f"f-{i}", "counterparty_id": "cp-a", "lgd": 0.5,
             "ead": [1.0, 1.0, 1.0]}
            for i in range(10001)
        ]
        with self.assertRaises(RequestTooLarge):
            self.call(facilities=facilities)

        # 1001 periods x 1000 facilities exceeds the pair budget.
        with self.assertRaises(RequestTooLarge):
            self.call(
                periods=list(range(1, 1002)),
                discount_factors=[1.0] * 1001,
                counterparties=[{"id": "cp-a", "cumulative_pd": [0.5] * 1001}],
                facilities=[
                    {"id": f"f-{i}", "counterparty_id": "cp-a", "lgd": 0.5,
                     "ead": [1.0] * 1001}
                    for i in range(1000)
                ],
            )

    def test_size_boundaries_are_allowed(self):
        counterparties = [
            {"id": f"cp-{i}", "cumulative_pd": [0.1, 0.2, 0.3]}
            for i in range(1000)
        ]
        facilities = [
            {"id": "f-1", "counterparty_id": "cp-0", "lgd": 0.5,
             "ead": [1.0, 1.0, 1.0]}
        ]
        result = self.call(counterparties=counterparties, facilities=facilities)
        self.assertEqual(len(result["counterparties"]), 1000)

        facilities = [
            {"id": f"f-{i}", "counterparty_id": "cp-a", "lgd": 0.5,
             "ead": [1.0, 1.0, 1.0]}
            for i in range(10000)
        ]
        result = self.call(facilities=facilities)
        self.assertEqual(len(result["facilities"]), 10000)

        # Exactly 1000 periods x 1000 facilities = 1000000 pairs.
        result = self.call(
            periods=list(range(1, 1001)),
            discount_factors=[1.0] * 1000,
